'use strict';
// Standalone, escaped HTML reports; the browser can print or save them as PDF.
var REPORT_LOGO='data:image/png;base64,',REPORT_SEQ=0;
function reportDocument(title,period,headers,rows,summary,notes,scope,columnWidths){
  var stamp=new Date().toLocaleString('ar-IQ-u-nu-latn',{timeZone:'Asia/Baghdad'}),widths={5:[5,24,20,18,33],4:[5,23,46,26],6:[5,23,17,13,17,25],7:[4,23,18,13,12,13,17],8:[5,17,14,15,8,20,11,10]},columns=(columnWidths||widths[headers.length]||[]).map(function(w){return '<col style="width:'+w+'%">';}).join('');
  function reportText(v){return englishDigits(v).split(/(\d+(?:[,.:\/-]\d+)*)/).map(function(s,i){var text=esc(s);return i%2?'<bdi dir="ltr" class="report-number">'+text+'</bdi>':text;}).join('');}
  function cells(values,tag){return values.map(function(v){return '<'+tag+'>'+(tag==='td'?reportText(v):displayEsc(v))+'</'+tag+'>';}).join('');}
  return '<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+displayEsc(title)+'</title><style>'+ 
    '@page{size:A4 portrait;margin:12mm}*{box-sizing:border-box}body{margin:0;color:#142750;background:white;font:13px Tahoma,Arial,sans-serif;line-height:1.7}main{max-width:190mm;margin:auto}.letterhead{display:flex;align-items:center;justify-content:space-between;border-bottom:3px solid #3154a1;padding-bottom:12px;margin-bottom:12px}.logo{width:115px;height:110px;object-fit:contain}.brand{font-size:22px;font-weight:bold}.english{font-size:12px;direction:ltr;text-align:right;color:#3154a1}h1{font-size:19px;margin:10px 0;text-align:center}.meta,.notes{font-size:12px;white-space:pre-line}.summary{padding:9px;margin:10px 0;border:1px solid #ccd5e8;background:#f4f7ff;white-space:pre-line}.report-number{white-space:nowrap}table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:12px;margin:14px 0}th,td{border:1px solid #a6b5d3;padding:7px;text-align:right;vertical-align:top;overflow-wrap:anywhere;white-space:pre-line}th{background:#eaf0ff;color:#173977;padding:4px;overflow-wrap:normal;word-break:normal}thead{display:table-header-group}tr{break-inside:avoid;page-break-inside:avoid}.signatures{display:flex;justify-content:space-between;gap:20px;margin-top:28px;border-top:1px solid #ccd5e8;padding-top:12px;break-inside:avoid}.foot{font-size:11px;color:#55637c;margin-top:15px}@media screen{body{padding:22px;background:#eef2fc}main{background:white;padding:22px;box-shadow:0 2px 12px #ccd5e8}}@media print{body{padding:0}main{max-width:none}th,.summary{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body><main><header class="letterhead"><div><div class="brand">مستشفى الدورة الأهلي</div><div class="english">AL-DORA PRIVATE HOSPITAL</div><div>شعبة الموارد البشرية</div></div><img class="logo" src="'+REPORT_LOGO+'" alt="شعار مستشفى الدورة الأهلي"></header><h1>'+displayEsc(title)+'</h1><div class="meta">الفترة: '+reportText(period)+'\nتاريخ إعداد التقرير: '+reportText(stamp)+'\nأعدّه: '+displayEsc((PROFILE||{}).fullName||(PROFILE||{}).label||(PROFILE||{}).username||'')+'\nالنطاق: '+displayEsc(scope||'الأقسام المسموحة للحساب الحالي')+'</div><div class="summary">'+displayEsc(summary||'')+'</div><table><colgroup>'+columns+'</colgroup><thead><tr>'+cells(headers,'th')+'</tr></thead><tbody>'+(rows.length?rows.map(function(r){return '<tr>'+cells(r,'td')+'</tr>';}).join(''):'<tr><td colspan="'+headers.length+'">لا توجد سجلات في الفترة المحددة</td></tr>')+'</tbody></table><div class="notes">'+displayEsc(notes||'')+'</div><div class="signatures"><span>إعداد / الموارد البشرية: ______________</span><span>اعتماد المسؤول: ______________</span></div><div class="foot">مستشفى الدورة الأهلي — تقرير صادر من نظام إدارة الموارد البشرية</div></main></body></html>';
}
function clearReport(){REPORT_SEQ++;var old=document.getElementById('hospital-report-frame');if(old)old.remove();}
var reportOldWipe=wipeData;wipeData=function(){clearReport();reportOldWipe();el('vio-report-month').value='';el('staff-report-dept').value='';};
function outputReport(html,filename,mode,session,permission){
  if(session!==SESSION||!SESSION_READY||!permission())return;
  if(mode==='export'){var url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=filename+'.html';document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url);},1000);return;}
  clearReport();var seq=REPORT_SEQ,frame=document.createElement('iframe');frame.id='hospital-report-frame';frame.title='تقرير المستشفى للطباعة';frame.style.cssText='position:fixed;width:1px;height:1px;left:-10000px;border:0';
  frame.onload=async function(){try{var doc=frame.contentDocument;await Promise.all(Array.from(doc.images).map(function(img){return img.complete?Promise.resolve():new Promise(function(resolve){img.onload=img.onerror=resolve;});}));if(doc.fonts)await doc.fonts.ready;if(seq!==REPORT_SEQ||session!==SESSION||!permission())return;frame.contentWindow.focus();frame.contentWindow.print();}catch(e){if(session===SESSION)alert('تعذر فتح الطباعة. استخدم تصدير التقرير ثم افتح الملف واطبعه.');}};frame.srcdoc=html;document.body.appendChild(frame);
}
function reportMonth(){var m=el('vio-report-month').value;if(!HR_CORE.F.month(m)){alert('اختر شهر التقرير أولًا');return null;}return m;}
function monthlyViolationReport(mode){
  if(!allowed('canViewVio'))return;var month=reportMonth();if(!month)return;
  var records=Object.values(VIOS).filter(function(v){return deptAllowed(v.deptId)&&!isBoard(v.deptId)&&v.status!=='cancelled'&&String(v.date||'').slice(0,7)===month&&(VFILTER==='all'||v.type===VFILTER);}).sort(function(a,b){return String(a.date).localeCompare(String(b.date));}),types={warning:'إنذار',deduct:'خصم',suspend:'إيقاف',praise:'تقدير'},total=0;
  var rows=records.map(function(v,i){var amount=v.deductionConfirmed===true?HR_CORE.F.money(v.deductionAmount):null;if(amount!==null)total+=amount;return [i+1,v.empName,deptTitle(v.deptId),v.date,v.type==='suspend'&&!v.suspend?'إنهاء خدمة':types[v.type]||v.type,v.reason,amount!==null?iq(amount):(v.type==='deduct'?'يحتاج اعتماد المبلغ':'—'),v.suspend||v.deduct||''];});
  outputReport(reportDocument('التقرير الشهري للعقوبات والمخالفات',month,['ت','الاسم','القسم','التاريخ','الإجراء','السبب','الخصم المعتمد','ملاحظات'],rows,'عدد السجلات: '+rows.length+' — إجمالي الخصومات المعتمدة: '+iq(total),'يعتمد اختيار الشهر على تاريخ المخالفة. الخصم غير المعتمد لا يدخل في الإجمالي. '+(VFILTER==='all'?'يشمل جميع أنواع الإجراءات.':'نوع الإجراء المختار: '+types[VFILTER])), 'aldora-violations-'+month,mode,SESSION,function(){return allowed('canViewVio');});
}
function staffSummaryReport(mode){
  if(!allowed('canViewReports'))return;var selected=el('staff-report-dept').value;if(selected&&(!deptAllowed(selected)||isBoard(selected)))return;var rows=[],counts=[],scope=selected?deptTitle(selected):'جميع الأقسام المسموحة للحساب الحالي';
  selectedStaffReportDeptIds().forEach(function(id){var employees=(LOCAL[id]||[]).filter(function(e){return e.status!=='terminated';});counts.push(deptTitle(id)+': '+employees.length);employees.forEach(function(e){rows.push([rows.length+1,deptTitle(id),e.name,e.role||'']);});});
  outputReport(reportDocument(selected?'ملخص موظفي '+deptTitle(selected):'ملخص الموظفين حسب الأقسام',today(),['ت','القسم','اسم الموظف','الصفة الوظيفية'],rows,'إجمالي الموظفين على رأس العمل: '+rows.length+'\n'+counts.join(' — '),'لا يشمل رئيس مجلس الإدارة ومعاون رئيس مجلس الإدارة أو من انتهت خدماتهم.',scope),'aldora-staff-'+today()+'-'+(selected||'all'),mode,SESSION,function(){return allowed('canViewReports')&&(!selected||deptAllowed(selected));});
}
async function monthlyDelayReport(key,mode){
  if(!allowed('canViewDelay')||!MONTHS[key])return;var month=MONTHS[key],groups=new Map(),total=0,legacy=0;
  Object.entries(month.depts||{}).forEach(function(pair){var dept=pair[0];if(!deptAllowed(dept)||isBoard(dept))return;Object.values(pair[1].employees||{}).filter(function(r){return r.status!=='cancelled';}).forEach(function(r){var id=dept+'/'+(r.employeeKey||'legacy:'+r.name),g=groups.get(id)||{dept:dept,name:r.name,amount:0,unknown:0,notes:[]},amount=r.deductionConfirmed===true?HR_CORE.F.money(r.deductionAmount):null;if(amount!==null){g.amount+=amount;total+=amount;}else{g.unknown++;legacy++;}g.notes.push((r.date||'')+(r.note?' — '+r.note:'')+(amount===null?' — سجل قديم لم يحدد له مبلغ':''));groups.set(id,g);});});
  var rows=Array.from(groups.values()).map(function(g,i){return [i+1,g.name,deptTitle(g.dept),g.unknown&&g.amount===0?'لم يحدد مبلغ':iq(g.amount)+(g.unknown?' — توجد سجلات قديمة':''),g.notes.join('\n')];});
  outputReport(reportDocument('التقرير الشهري لمبالغ تأخير البصمة',month.name,['ت','الاسم','القسم','مبلغ التأخير (د.ع)','الملاحظات'],rows,'عدد الموظفين: '+rows.length+' — إجمالي مبالغ التأخير: '+iq(total)+(legacy?'\nسجلات قديمة بلا مبلغ: '+legacy:''),'يُخصم مبلغ كل سجل تلقائيًا من راتب شهر تاريخه. لا يضيف تصدير التقرير أو طباعته خصمًا جديدًا. السجلات القديمة بالدقائق لا تُحتسب مالياً حتى تحديد مبلغها.'),'aldora-fingerprint-'+key,mode,SESSION,function(){return allowed('canViewDelay');});
}
